 const optionRow=(label,description,control)=><View key={label} style={s.optionRow}><View style={{flex:1,paddingRight:12,minWidth:0}}><Text style={{color:theme.text,fontSize:15,fontWeight:'700'}}>{label}</Text>{description?<Text style={{color:theme.muted,fontSize:12,marginTop:4,lineHeight:17}}>{description}</Text>:null}</View><View style={{maxWidth:'54%',alignItems:'flex-end',justifyContent:'center'}}>{control}</View></View>;
 const optionToggle=(label,key,description)=>optionRow(label,description,<Switch accessibilityLabel={label} value={!!settingsDraft[key]} onValueChange={v=>{tap();setSettingsDraft(p=>({...p,[key]:v}));}} trackColor={{false:theme.line,true:theme.accent2}} thumbColor={settingsDraft[key]?theme.accent:'#bcb5a7'}/>);
 const optionChoices=(label,key,description,values)=>optionRow(label,description,<Pressable accessibilityRole="button" accessibilityLabel={label+', '+fmt(settingsDraft[key]||values[0])} onPress={()=>{tap();Alert.alert(label,description||'Choose an option.',[...values.map(v=>({text:fmt(v),onPress:()=>setSettingsDraft(p=>({...p,[key]:v,...(key==='provider'&&v!==p.provider?{apiKey:'',model:'auto',endpoint:''}:{})}))})),{text:'Cancel',style:'cancel'}]);}} style={[s.choiceLine,{borderColor:theme.line,backgroundColor:theme.panel2,minWidth:110,justifyContent:'space-between'}]}><Text numberOfLines={1} style={{color:theme.accent,fontSize:13,fontWeight:'800'}}>{fmt(settingsDraft[key]||values[0])}  ▾</Text></Pressable>);
 const optionSlider=(label,key,description,min,max,step=0.05)=>optionRow(label,description,<View style={{width:Math.min(150,screenWidth*.4),alignItems:'flex-end'}}><Text style={{color:theme.accent,fontSize:12,fontWeight:'800'}}>{key==='music'||key==='sfx'?Math.round((settingsDraft[key]||0)*100)+'%':key==='voice'?(settingsDraft.voice||1).toFixed(2)+'×':Math.round(settingsDraft[key]||min)+' pt'}</Text><Pressable accessibilityRole="adjustable" accessibilityLabel={label} accessibilityValue={{min,max,now:Number(settingsDraft[key]??min)}} onPress={e=>{const x=Math.max(0,Math.min(1,e.nativeEvent.locationX/150));const raw=min+x*(max-min);setSettingsDraft(p=>({...p,[key]:Math.max(min,Math.min(max,Math.round(raw/step)*step))}));}} style={{height:44,width:'100%',justifyContent:'center'}}><View style={{height:5,borderRadius:3,backgroundColor:theme.line}}/><View style={{position:'absolute',left:0,width:Math.max(0,Math.min(1,((Number(settingsDraft[key]??min)-min)/(max-min||1))))*100+'%',height:5,borderRadius:3,backgroundColor:theme.accent}}/></Pressable></View>);
 const options=()=> <View style={{flex:1}}>{page==='Hub'?<ScrollView contentContainerStyle={s.optionsHub} keyboardShouldPersistTaps="handled"><View style={s.optionsHeading}><Text style={[s.eyebrow,{color:theme.accent}]}>SYSTEM CONFIGURATION</Text><Text style={[s.title,{color:theme.text,fontSize:30,marginTop:6}]}>Options</Text><Text style={{color:theme.muted,marginTop:5}}>Tune your next run. Changes apply when saved.</Text>{settingsDirty?<Text accessibilityLiveRegion="polite" style={{color:theme.accent,fontSize:12,fontWeight:'800',marginTop:8}}>● Unsaved changes</Text>:null}</View><View style={s.tileGrid}>{OPTION_TILES.map(tile=><Pressable key={tile.id} accessibilityRole="button" accessibilityLabel={tile.id+', '+tileStatus(tile.id)+(pageDirty(tile.id)?', unsaved changes':'')} onPress={()=>{tap();setPage(tile.id);setStatus('');}} style={({pressed})=>[s.optionTile,{backgroundColor:theme.panel,borderColor:pageDirty(tile.id)?theme.accent:theme.line,opacity:pressed?.88:1,width:(screenWidth-56)/2}]}><Text style={[s.tileIcon,{color:theme.accent}]}>{tile.icon}</Text><View style={{flexDirection:'row',alignItems:'center',gap:5}}><Text style={[s.tileTitle,{color:theme.text,flex:1}]}>{tile.id}</Text>{pageDirty(tile.id)?<View style={s.dirtyDot}/>:null}</View><Text style={{color:theme.accent,fontSize:12,fontWeight:'700',marginTop:5}} numberOfLines={2}>{tileStatus(tile.id)}</Text><Text style={{color:theme.muted,fontSize:11,marginTop:6,lineHeight:15}} numberOfLines={2}>{tile.subtitle}</Text><Text style={{color:theme.muted,fontSize:16,marginTop:8,alignSelf:'flex-end'}}>›</Text></Pressable>)}</View><View style={{height:16}}/></ScrollView>:<Animated.View style={{flex:1,opacity:pageTransition,transform:[{translateX:pageTransition.interpolate({inputRange:[0.72,1],outputRange:[20,0]})}]}}><View style={s.detailHeader}><Pressable accessibilityRole="button" accessibilityLabel="Back to Options" onPress={leaveOptions} style={[s.backButton,{borderColor:theme.line,backgroundColor:theme.panel}]}><Text style={{color:theme.accent,fontSize:22}}>‹</Text><Text style={{color:theme.text,fontWeight:'700'}}>Options</Text></Pressable><Text style={[s.title,{color:theme.text,fontSize:28,marginTop:16}]}>{page}</Text><Text style={{color:theme.muted,marginTop:5,marginBottom:12}}>{OPTION_TILES.find(t=>t.id===page)?.subtitle||'Manage your settings'}</Text>{pageDirty(page)?<Text accessibilityLiveRegion="polite" style={{color:theme.accent,fontSize:12,fontWeight:'800'}}>● Unsaved changes on this page</Text>:null}</View><ScrollView contentContainerStyle={s.detailContent} keyboardShouldPersistTaps="handled">
 {page==='Story'&&<>{section('STORY SHAPE',<>{optionChoices('Story style','storyStyle','Choose a style or let the game choose each run.',['Randomize',...STYLES])}<View style={{paddingVertical:10}}><Text style={{color:theme.text,fontWeight:'700'}}>Custom premise</Text><Text style={{color:theme.muted,fontSize:12,marginTop:4,marginBottom:8}}>Optional: describe a setting or mystery. AI narration must be enabled for the prompt to rewrite the story.</Text><TextInput accessibilityLabel="Custom story premise" value={settingsDraft.premise||''} onChangeText={v=>setSettingsDraft(p=>({...p,premise:v}))} multiline placeholder="Describe a place, threat, mystery…" placeholderTextColor={theme.muted} style={[s.input,{color:theme.text,backgroundColor:theme.bg,borderColor:theme.line,minHeight:90}]}/></View><TextInput accessibilityLabel="Optional story seed" value={settingsDraft.seed||''} onChangeText={v=>setSettingsDraft(p=>({...p,seed:v}))} placeholder="Optional seed" placeholderTextColor={theme.muted} style={[s.input,{color:theme.text,backgroundColor:theme.bg,borderColor:theme.line,marginBottom:12}]}/>{optionChoices('Pacing','pacing','Set the story tempo.',['Slow burn','Balanced','Relentless'])}{optionChoices('Passage detail','length','How much text you want per scene. Brief is fastest to read; Rich gives more atmosphere.',['Brief','Standard','Rich'])}{optionChoices('Content intensity','intensity','Choose the level of horror.',['Mild','Moderate','Intense'])}</>)}</>}
 {page==='Gameplay'&&<>{section('CHALLENGE',<>{optionChoices('Difficulty','difficulty','Story: forgiving. Standard: balanced. Hardcore: scarce safety nets. Nightmare: toughest checks and consequences.',['Story','Standard','Hardcore','Nightmare'])}{optionToggle('Show odds preview','odds','Display estimated success chance before risky actions.')}{optionChoices('Story length','length','How long a typical run should feel: Short (quick session), Standard (balanced), Long (more exploration), Endless (keep playing until an ending).',['Short','Standard','Long','Endless'])}</>)}</>}
 {page==='Narrator Voice'&&<>{section('SPOKEN NARRATION',<>{optionToggle('Read aloud','readAloud','Use the iPhone system voice when requested.')}{optionToggle('Automatically read new passages','autoRead','Speak each new scene. Stops when you leave the game.')}{optionSlider('Speech rate','voice','Adjust the iPhone voice speed.',0.5,1.5,0.05)}<Button theme={theme} secondary onPress={()=>{tap();Speech.speak('Every path ends somewhere.',{rate:settingsDraft.voice||1});}}>Preview voice</Button></>)}</>}
 {page==='AI Connection'&&<>{section('AI PROVIDER',<>{optionToggle('Enable AI narrator','aiEnabled','AI rewrites story passages and adapts custom actions. Preset stories still start without AI; add a valid key to use live narration.')}{optionChoices('Provider','provider','Choose which API provider to use. Switching providers clears the key field.',['groq','google'])}<View style={{marginTop:8,marginBottom:8}}><Text style={{color:theme.text,fontWeight:'700'}}>{settingsDraft.provider==='groq'?'Groq API key':'Google AI Studio API key'}</Text><Text style={{color:theme.muted,fontSize:12,marginTop:4,marginBottom:8}}>Stored securely in iOS Keychain. Never included in game saves. Model selection is automatic.</Text><View style={{flexDirection:'row',gap:8,alignItems:'center'}}><TextInput accessibilityLabel={settingsDraft.provider==='groq'?'Groq API key':'Google AI Studio API key'} value={settingsDraft.apiKey||''} onChangeText={v=>{setSettingsDraft(p=>({...p,apiKey:v,model:'auto',endpoint:''}));setAiTest(null);}} secureTextEntry={!showApiKey} autoCapitalize="none" autoCorrect={false} spellCheck={false} placeholder="Paste API key" placeholderTextColor={theme.muted} keyboardAppearance="dark" style={[s.input,{flex:1,minWidth:0,color:theme.text,backgroundColor:theme.bg,borderColor:theme.line}]}/><Pressable accessibilityRole="button" onPress={()=>setShowApiKey(v=>!v)} style={[s.smallAction,{borderColor:theme.line}]}><Text style={{color:theme.text}}>{showApiKey?'Hide':'Show'}</Text></Pressable><Pressable accessibilityRole="button" onPress={async()=>{const value=await Clipboard.getStringAsync();if(value)setSettingsDraft(p=>({...p,apiKey:value.trim()}));setAiTest(null);tap();}} style={[s.smallAction,{borderColor:theme.line}]}><Text style={{color:theme.text}}>Paste</Text></Pressable></View><Text style={{color:theme.muted,fontSize:11,lineHeight:16,marginTop:8}}>Only the current scene and action are sent to {settingsDraft.provider==='groq'?'Groq':'Google'} when AI narration is enabled. Your key stays in Keychain.</Text><Text style={{color:theme.muted,fontSize:11,lineHeight:16,marginTop:5}}>{settingsDraft.provider==='groq'?'Groq free-tier rate limits apply.':'Google Gemini free-tier quotas apply.'}</Text></View><Button theme={theme} secondary disabled={testingAI} onPress={testAI}>{testingAI?'TESTING CONNECTION…':'TEST CONNECTION'}</Button>{aiTest?<View accessibilityLiveRegion="polite" style={[s.statusChip,{borderColor:aiTest.kind==='success'?theme.good:aiTest.kind==='error'?theme.danger:theme.line,backgroundColor:aiTest.kind==='success'?'#102719':aiTest.kind==='error'?'#2b1111':theme.panel2}]}><View style={{width:8,height:8,borderRadius:4,backgroundColor:aiTest.kind==='success'?theme.good:aiTest.kind==='error'?theme.danger:theme.accent,marginTop:5}}/><View style={{flex:1}}><Text style={{color:aiTest.kind==='success'?theme.good:aiTest.kind==='error'?theme.danger:theme.text,fontWeight:'800'}}>{aiTest.kind==='success'?'CONNECTED':aiTest.kind==='error'?'CONNECTION FAILED':'TESTING'}</Text><Text style={{color:theme.text,fontSize:12,marginTop:3,lineHeight:17}}>{aiTest.message}</Text></View></View>:null}</>)}</>}{page==='Audio & Haptics'&&<>{section('SOUND',<>{optionToggle('Haptics','haptics','Subtle feedback for choices and controls.')}{optionToggle('Ambient sound','ambient','Enable ambient audio when the audio layer is available.')}{optionSlider('Music volume','music','Set background music level.',0,1,0.05)}{optionSlider('Sound effects','sfx','Set sound effects level.',0,1,0.05)}</>)}</>}
 {page==='Display & Accessibility'&&<>{section('APPEARANCE',<>{optionChoices('Color theme','theme','Choose a palette. Extra themes unlock by completing runs on harder difficulties.',availableThemes)}{optionChoices('Effects quality','effects','Balance visual effects and performance.',['High','Balanced','Low'])}{optionToggle('Reduce Motion','reduceMotion','Reduce movement and animation.')}{optionSlider('Story text size','textSize','Set passage text size.',14,25,1)}</>)}</>}
 {page==='Data'&&<>{section('LOCAL DATA',<><Text style={{color:theme.muted,fontSize:12,lineHeight:18,marginBottom:12}}>Saves, profile, and gameplay settings stay on this device. The API key is stored separately in iOS Keychain.</Text><Button theme={theme} secondary onPress={()=>Alert.alert('Forget API key?','This removes the saved Gemini key from this device.',[{text:'Cancel',style:'cancel'},{text:'Forget key',style:'destructive',onPress:async()=>{const next={...settingsDraft,apiKey:''};setSettingsDraft(next);await persistSettings(next);setAiTest(null);}}])}>Forget API key</Button><View style={{height:12}}/><Button theme={theme} secondary onPress={()=>Alert.alert('Reset local data?','This deletes local saves, profile, settings, and the saved API key.',[{text:'Cancel',style:'cancel'},{text:'Reset data',style:'destructive',onPress:async()=>{await clearAll();const reset={...DEFAULT};setSettings(reset);setSettingsDraft(reset);setProfile({runs:0,deaths:0,endings:[],achievements:[],bestRoll:null,worstRoll:null,score:0});setPage('Hub');}}])}>Reset local data</Button></>)}</>}
 </ScrollView></Animated.View>}
 <View style={[s.optionsBottomBar,{backgroundColor:theme.bg,borderTopColor:theme.line}]}><Pressable accessibilityRole="button" onPress={cancelOptions} style={[s.bottomCancel,{borderColor:theme.line}]}><Text style={{color:theme.text,fontWeight:'800'}}>Cancel</Text></Pressable><View style={{flex:1}}>{settingsDirty?<Text style={{color:theme.accent,fontSize:11,fontWeight:'800',textAlign:'center'}}>UNSAVED CHANGES</Text>:<Text style={{color:theme.muted,fontSize:11,textAlign:'center'}}>OPTIONS</Text>}</View><Pressable accessibilityRole="button" onPress={saveOptions} style={[s.bottomSave,{backgroundColor:theme.accent,borderColor:theme.accent}]}><Text style={{color:theme.ink,fontWeight:'900'}}>Save</Text></Pressable></View></View>;
 const menu=()=> <ScrollView contentContainerStyle={s.menuContent}><Logo theme={theme}/><Text style={[s.eyebrow,{color:theme.accent,textAlign:'center'}]}>A SURVIVAL HORROR ADVENTURE</Text><View style={{height:18}}/>{[['CONTINUE',async()=>{const rows=await listSaves();const autosave=rows.find(v=>v.slot==='autosave');if(autosave)await resumeSave(autosave.key);else setScreen('game');}],['NEW GAME',()=>{const cards=premiseShuffle(String(Date.now()),profile.premiseHistory||[],3);setTaleCards(cards);setSelectedPremise(cards[0]||null);setSetupAdvanced(false);setScreen('setup');}],['LOAD GAME',async()=>{await refreshSaves();setScreen('saves');}],['JOURNAL & ENDINGS',()=>setScreen('journal')],['ACHIEVEMENTS / PROFILE',()=>setScreen('profile')],['OPTIONS',openOptions],['HOW TO PLAY',()=>setScreen('howto')],['ABOUT / CREDITS',()=>setScreen('about')]].map(([label,fn],i)=><View key={label} style={{marginBottom:9}}><Button theme={theme} secondary={i!==1} onPress={fn}>{label}</Button></View>)}<Text style={{color:theme.muted,textAlign:'center',marginTop:14,fontSize:11}}>DEADEND · VERSION 1.2</Text></ScrollView>;
 const heading=(title,sub)=> <View style={{marginBottom:18}}><Text style={[s.title,{color:theme.text}]}>{title}</Text>{sub?<Text style={{color:theme.muted,marginTop:5}}>{sub}</Text>:null}</View>;
 const field=(label,value,onChange,placeholder='',opts={})=><View style={{marginBottom:14}} key={label}><Text style={[s.label,{color:theme.muted}]}>{label}</Text><TextInput value={String(value??'')} onChangeText={onChange} placeholder={placeholder} placeholderTextColor={theme.muted} secureTextEntry={opts.secure} multiline={opts.multiline} keyboardAppearance="dark" style={[s.input,{color:theme.text,backgroundColor:theme.panel,borderColor:theme.line,minHeight:opts.multiline?88:46}]} /></View>;
 const selector=(label,value,values,onChange)=><View style={{marginBottom:15}} key={label}><Text style={[s.label,{color:theme.muted}]}>{label}</Text><Pressable accessibilityRole="button" accessibilityLabel={label+', '+value} onPress={()=>{tap();Alert.alert(label,'Choose an option.',[...values.map(v=>({text:fmt(v),onPress:()=>onChange(v)})),{text:'Cancel',style:'cancel'}]);}} style={{marginTop:7,paddingHorizontal:13,paddingVertical:12,borderWidth:1,borderColor:theme.line,backgroundColor:theme.panel,borderRadius:10,minHeight:44,flexDirection:'row',justifyContent:'space-between',alignItems:'center'}}><Text style={{color:theme.text,fontSize:14,fontWeight:'700'}}>{fmt(value)}</Text><Text style={{color:theme.accent,fontSize:16}}>▾</Text></Pressable></View>;
 const toggle=(label,key,description)=> <View key={key} style={[s.toggle,{borderColor:theme.line}]}><View style={{flex:1,paddingRight:12}}><Text style={{color:theme.text,fontWeight:'700'}}>{label}</Text>{description?<Text style={{color:theme.muted,fontSize:12,marginTop:4}}>{description}</Text>:null}</View><Switch value={!!settingsDraft[key]} onValueChange={v=>setSettingsDraft(p=>({...p,[key]:v}))} trackColor={{false:theme.line,true:theme.accent2}} thumbColor={settingsDraft[key]?theme.accent:'#bcb5a7'}/></View>;
 const game=()=> <KeyboardAvoidingView style={{flex:1}} behavior={Platform.OS==='ios'?'padding':undefined} keyboardVerticalOffset={12}><View style={{flexDirection:'row',alignItems:'center',gap:7,padding:12}}><Meter label="HEALTH" value={state.health} icon="♥" theme={theme}/><Meter label="SANITY" value={state.sanity} icon="◈" theme={theme}/><Pressable onPress={()=>{tap();setInventoryOpen(v=>!v);}} accessibilityLabel="Open inventory" style={[s.pause,{borderColor:theme.line,width:54,backgroundColor:theme.panel}]}><Text style={{color:theme.accent,fontWeight:'900',fontSize:10}}>BAG {(state.inventory||[]).length}/3</Text></Pressable><Pressable onPress={()=>setScreen('pause')} accessibilityLabel="Pause game" style={[s.pause,{borderColor:theme.line}]}><Text style={{color:theme.accent,fontWeight:'900'}}>Ⅱ</Text></Pressable></View><View style={{paddingHorizontal:12}}>{inventoryOpen&&<View style={{padding:10,marginBottom:8,borderWidth:1,borderRadius:8,borderColor:theme.line,backgroundColor:theme.panel}}><Text style={{color:theme.accent,fontWeight:'900',marginBottom:7}}>CARRIED ITEMS · {(state.inventory||[]).length}/3</Text>{(state.inventory||[]).length===0?<Text style={{color:theme.muted,fontSize:12}}>Your pack is empty. Items you collect will appear here.</Text>:(state.inventory||[]).map((item,i)=><View key={String(item)+i} style={{flexDirection:'row',alignItems:'center',justifyContent:'space-between',paddingVertical:5}}><Text style={{color:theme.text,flex:1}}>{String(item)}</Text><Pressable onPress={()=>{tap();const next={...state,inventory:(state.inventory||[]).filter((_,idx)=>idx!==i),history:[...(state.history||[]),{action:'Drop '+String(item),from:state.nodeId,nodeId:state.nodeId,outcome:'item dropped'}]};setState(next);setStatus('Dropped '+String(item)+'.');saveRun('autosave',{state:next,scene,style,premise,turn:next.turn||0,settings:{...settings,apiKey:''}}).then(refreshSaves).catch(()=>{});}}><Text style={{color:theme.danger,fontSize:11,fontWeight:'900'}}>DROP</Text></Pressable></View>)}</View>}</View><View style={{paddingHorizontal:16,paddingBottom:8,flexDirection:'row',justifyContent:'space-between'}}><Text style={[s.eyebrow,{color:theme.accent}]}>{style.toUpperCase()}</Text><Text style={{color:theme.muted,fontSize:11}}>TURN {state.turn||0} · {fmt(state.nodeId)}</Text></View><ScrollView style={{flex:1}} contentContainerStyle={{padding:16,paddingTop:6}} keyboardShouldPersistTaps="handled"><Animated.Text style={[s.story,{color:theme.text,fontSize:settings.textSize||17,transform:[{translateX:state.sanity==='Breaking'||state.sanity==='Lost'?sanityWarp.interpolate({inputRange:[-1,1],outputRange:[-5,5]}):0},{scale:state.sanity==='Lost'?sanityWarp.interpolate({inputRange:[-1,1],outputRange:[1,1.015]}):1}]}]}>{scene}</Animated.Text>{status.startsWith('AI narration unavailable:')&&<View accessibilityLiveRegion="polite" style={{borderWidth:1,borderColor:theme.danger,borderRadius:8,padding:10,marginBottom:12,backgroundColor:theme.panel}}><Text style={{color:theme.danger,fontWeight:'800',fontSize:12}}>AI NARRATION UNAVAILABLE</Text><Text style={{color:theme.text,fontSize:12,marginTop:4}}>{status}</Text></View>}{busy&&<Text style={{color:theme.accent,marginVertical:12}}>The narrator is considering…</Text>}{(getCurrentNode(state)?.choices||[]).map((c,i)=><Pressable key={c.text+i} disabled={busy} onPress={()=>choose(c)} style={[s.choice,{backgroundColor:theme.panel,borderColor:theme.line,opacity:busy ? 0.5 : 1}]}><Text style={{color:theme.accent,fontSize:11,fontWeight:'900',marginBottom:4}}>OPTION {String(i+1).padStart(2,'0')}{c.dc?' · '+(c.dc>=19?'EXTREME':c.dc>=16?'HARD':c.dc>=13?'MODERATE':'EASY')+' CHECK':''}</Text><Text style={{color:theme.text,fontSize:14,fontWeight:'600'}}>{c.text}</Text></Pressable>)}<Text style={[s.label,{color:theme.muted,marginTop:12}]}>OR TRY SOMETHING ELSE</Text><View style={{flexDirection:'row',flexWrap:'wrap',gap:6,marginVertical:8}}>{['Examine','Listen','Search','Force','Hide','Run','Climb','Use item'].map(v=><Pressable key={v} onPress={()=>setAction(p=>p?(p+' '+v.toLowerCase()):v+' ')} style={[s.chip,{borderColor:theme.line}]}><Text style={{color:theme.muted,fontSize:11}}>{v}</Text></Pressable>)}</View><View style={{flexDirection:'row',gap:7}}><TextInput value={action} onChangeText={setAction} onSubmitEditing={customAct} placeholder="Describe your action…" placeholderTextColor={theme.muted} maxLength={200} returnKeyType="send" style={[s.input,{flex:1,color:theme.text,backgroundColor:theme.panel,borderColor:theme.line}]} /><View style={{width:90}}><Button theme={theme} onPress={customAct} disabled={busy}>ACT</Button></View></View>{settings.readAloud&&<View style={{marginTop:10}}><Button theme={theme} secondary small onPress={()=>speak(scene)}>READ PASSAGE</Button></View>}</ScrollView>{showRoll&&<View style={s.modalScrim}><Dice roll={roll} theme={theme} onDone={finishRoll}/></View>}</KeyboardAvoidingView>;
 const savesScreen=()=> <ScrollView contentContainerStyle={s.pageContent}>{heading('LOAD GAME','Autosave and manual slots on this device.')}{saves.length===0?<Text style={{color:theme.muted,marginBottom:18}}>No saved games yet. Save from the pause menu during a run.</Text>:saves.map(item=><View key={item.key} style={[s.choice,{backgroundColor:theme.panel,borderColor:theme.line}]}><Text style={{color:theme.text,fontWeight:'800'}}>SLOT {item.slot||'?'} · {item.style||'Unknown tale'}</Text><Text style={{color:theme.muted,fontSize:12,marginVertical:5}}>{item.corrupt?'Save cannot be read':('Turn '+(item.turn||0)+' · '+new Date(item.savedAt||0).toLocaleString())}</Text><Button theme={theme} small disabled={!!item.corrupt} onPress={()=>resumeSave(item.key)}>LOAD THIS SAVE</Button></View>)}{[1,2,3].map(n=><View key={n} style={{marginBottom:8}}><Button theme={theme} secondary onPress={()=>save(String(n))}>SAVE CURRENT RUN TO SLOT {n}</Button></View>)}<Button theme={theme} secondary onPress={()=>setScreen('menu')}>BACK</Button></ScrollView>;
 const pause=()=> <ScrollView contentContainerStyle={s.menuContent}>{heading('PAUSED','Your run is waiting.')}{[['RESUME',()=>setScreen('game')],['JOURNAL',()=>setScreen('journal')],['INVENTORY',()=>setStatus('Inventory: '+((state.inventory||[]).join(', ')||'Empty'))],['OPTIONS',openOptions],['SAVE GAME',()=>setScreen('saves')],['QUIT TO MENU',()=>setScreen('menu')]].map(([l,f])=><View key={l} style={{marginBottom:8}}><Button theme={theme} secondary onPress={f}>{l}</Button></View>)}{status?<Text style={{color:theme.accent,marginTop:10}}>{status}</Text>:null}</ScrollView>;
 const journal=()=> <ScrollView contentContainerStyle={s.pageContent}>{heading('JOURNAL & ENDINGS','Your actions leave a record.')}{(state.history||[]).length===0?<Text style={{color:theme.muted}}>No actions recorded in this run.</Text>:(state.history||[]).slice().reverse().map((h,i)=><View key={i} style={[s.choice,{backgroundColor:theme.panel,borderColor:theme.line}]}><Text style={{color:theme.text,fontWeight:'700'}}>{h.action}</Text><Text style={{color:theme.muted,fontSize:12,marginTop:4}}>{fmt(h.outcome)} · {h.from} → {h.nodeId}</Text>{h.roll?<Text style={{color:theme.accent,fontSize:12}}>D20 {h.roll.raw} · total {h.roll.total}</Text>:null}</View>)}<Text style={[s.section,{color:theme.accent}]}>ENDINGS CODEX</Text>{['ending_escape','ending_truth','ending_dead','ending_lost'].map(v=><Text key={v} style={{color:theme.muted,marginBottom:8}}>◇  {profile.endings?.includes(v)?fmt(v):'??????'}</Text>)}<Button theme={theme} secondary onPress={()=>setScreen('game')}>RETURN TO STORY</Button></ScrollView>;
 const profileScreen=()=> <ScrollView contentContainerStyle={s.pageContent}>{heading('PROFILE & ACHIEVEMENTS','A record of your survival.')}{[['Runs',profile.runs||0],['Deaths',profile.deaths||0],['Endings found',(profile.endings||[]).length],['Achievement score',profile.score||0]].map(([k,v])=><View key={k} style={[s.stat,{borderColor:theme.line}]}><Text style={{color:theme.muted}}>{k}</Text><Text style={{color:theme.accent,fontSize:22,fontWeight:'900'}}>{v}</Text></View>)}<Text style={[s.section,{color:theme.accent}]}>ACHIEVEMENTS</Text>{ACHIEVEMENTS.map(item=>{const earned=(profile.achievements||[]).includes(item.id);return <View key={item.id} style={[s.choice,{backgroundColor:theme.panel,borderColor:theme.line,opacity:earned?1:.65}]}><Text style={{color:earned?theme.accent:theme.muted,fontWeight:'800'}}>{earned?'◆':item.hidden?'◇':'○'}  {earned||!item.hidden?item.title:'Undiscovered'}</Text><Text style={{color:theme.muted,fontSize:12,marginTop:4}}>{earned||!item.hidden?item.description:'A hidden achievement.'} · {item.points} points</Text></View>;})}<Button theme={theme} secondary onPress={()=>setScreen('menu')}>BACK TO MENU</Button></ScrollView>;
 let body;
 if(screen==='splash')body=<View style={s.center}><Logo theme={theme}/><Text style={{color:theme.muted}}>EVERY PATH ENDS SOMEWHERE.</Text></View>;
 else if(screen==='warning')body=<View style={s.pageContent}>{heading('CONTENT WARNING','DeadEnd contains fictional horror, peril, psychological distress and character death.') }<Text style={[s.story,{color:theme.text,fontSize:settings.textSize||17,lineHeight:Math.round((settings.textSize||17)*1.6)}]}>The intensity can be adjusted in Options. You can stop or leave a run at any time.</Text><Button theme={theme} onPress={async()=>{const p={...profile,onboarded:true};setProfile(p);await writeProfile(p);setScreen('onboarding');}}>CONTINUE</Button></View>;
 else if(screen==='onboarding')body=<View style={s.pageContent}>{heading(['MAKE CHOICES','ROLL FOR RISK','TRY ANY ACTION'][onboard],['Each decision changes the path you explore.','Risky actions use a twenty-sided die; your condition can affect the result.','Type a plausible action in your own words. The engine decides the outcome.'][onboard])}<View style={[s.choice,{backgroundColor:theme.panel,borderColor:theme.line}]}><Text style={{color:theme.text,lineHeight:24}}>{['Choices lead to locations, discoveries and different endings. Some paths are safer than others.','A natural 1 is a critical failure. A natural 20 is a critical success. Partial success can still carry a cost.','The built-in game works offline. AI narration is optional and can describe your attempt in more detail.'][onboard]}</Text></View><Button theme={theme} onPress={()=>onboard<2?setOnboard(onboard+1):setScreen('title')}>{onboard<2?'NEXT':'BEGIN'}</Button><View style={{height:10}}/><Button theme={theme} secondary onPress={()=>setScreen('title')}>SKIP</Button></View>;
